<?php
declare(strict_types=1);

function icon(string $name): string {
    $paths=['grid'=>'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','ticket'=>'M4 4h16v5a3 3 0 0 0 0 6v5H4v-5a3 3 0 0 0 0-6z M14 7v2m0 3v1m0 3v1','calendar'=>'M4 5h16v16H4z M7 2v6m10-6v6M4 11h16','users'=>'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M13 3.13a4 4 0 0 1 0 7.75 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0','box'=>'m12 3 9 5v9l-9 5-9-5V8z M3 8l9 5 9-5m-9 5v9M7 5l10 6','file'=>'M14 2H4v20h16V8z M14 2v6h6M8 13h8m-8 4h8','money'=>'M3 6h18v14H3z M3 10h18m-5 5h2','settings'=>'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 3 2 2-1 3 2 3 3-1 3 2 3-2 3 1 2-3-1-3 2-2-2-3-3-1-1-3z','arrow'=>'M5 12h14m-5-5 5 5-5 5','plus'=>'M12 5v14M5 12h14','check'=>'m5 12 4 4L19 6','clock'=>'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0','link'=>'M10 13a5 5 0 0 0 7 .3l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.3l-3 3a5 5 0 0 0 7 7l2-2','search'=>'m21 21-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0','logout'=>'M9 3H3v18h6 M9 12h13m-5-5 5 5-5 5','wrench'=>'m14 6 4-4a6 6 0 0 1-7 8L4 19a2 2 0 0 1-3-3l9-7a6 6 0 0 1 8-7l-4 4z'];
    return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'.($paths[$name]??$paths['grid']).'"/></svg>';
}
function field(string $label, string $name, string $type='text', $value='', bool $required=true, string $extra=''): void { echo '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.($required?'required ':'').$extra.'></label>'; }
function area(string $label,string $name,$value='',bool $required=false): void { echo '<label>'.e($label).'<textarea name="'.e($name).'" rows="3" '.($required?'required':'').'>'.e($value).'</textarea></label>'; }
function select_field(string $label,string $name,array $options,$value=''): void { echo '<label>'.e($label).'<select name="'.e($name).'">'; foreach ($options as $k=>$v) echo '<option value="'.e($k).'" '.((string)$k===(string)$value?'selected':'').'>'.e($v).'</option>'; echo '</select></label>'; }
function start_form(string $action, array $hidden=[],string $class='form-grid'): void { echo '<form method="post" class="'.e($class).'">'.csrf().'<input type="hidden" name="action" value="'.e($action).'">'; foreach($hidden as $k=>$v) echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">'; }
function end_form(string $label='Save changes'): void { echo '<div class="form-actions"><button class="button" type="submit">'.e($label).'</button></div></form>'; }
function heading(string $eyebrow,string $title,string $description,string $action=''): void { echo '<div class="page-heading"><div><div class="eyebrow">'.e($eyebrow).'</div><h1>'.e($title).'</h1><p>'.e($description).'</p></div>'.$action.'</div>'; }
function empty_state(string $title,string $message,string $link='',string $label='Get started'): void { echo '<div class="empty">'.icon('box').'<h3>'.e($title).'</h3><p>'.e($message).'</p>'.($link?'<a class="button small" href="'.e($link).'">'.e($label).'</a>':'').'</div>'; }
function staff_options(): array { global $user; $options=['0'=>'Unassigned']; foreach(all('SELECT id,name FROM users WHERE business_id=? ORDER BY name',[$user['business_id']]) as $u) $options[$u['id']]=$u['name']; return $options; }
function status_options(): array { return ['open'=>'Open','scheduled'=>'Scheduled','in_progress'=>'In progress','waiting'=>'Waiting','completed'=>'Completed','cancelled'=>'Cancelled']; }
function ticket_list(array $tickets): void {
    if (!$tickets) { empty_state('No tickets yet','New customer requests will appear here. Create a ticket or share your request page.'); return; }
    echo '<div class="table-scroll"><table><thead><tr><th>Ticket / service</th><th>Customer</th><th>Status</th><th>Priority</th><th>Appointment</th><th>Assigned to</th><th></th></tr></thead><tbody>';
    foreach($tickets as $t) echo '<tr><td><a class="ticket-title" href="'.e(url(['page'=>'ticket','id'=>$t['id']])).'"><span class="mono">'.ticket_number((int)$t['id']).'</span> '.e($t['title']).'</a><small>'.e($t['service_name']).'</small></td><td>'.e($t['customer_name']).'</td><td>'.badge($t['status']).'</td><td><span class="priority '.e($t['priority']).'">'.e(ucfirst($t['priority'])).'</span></td><td>'.($t['scheduled_at']?e(date('d M, H:i',strtotime($t['scheduled_at']))):'<span class="muted">Not scheduled</span>').'</td><td>'.e($t['assignee']??'Unassigned').'</td><td><a class="icon-link" aria-label="Open ticket" href="'.e(url(['page'=>'ticket','id'=>$t['id']])).'">'.icon('arrow').'</a></td></tr>';
    echo '</tbody></table></div>';
}
function ticket_query(string $extra='',array $args=[]): array { global $user; $sql='SELECT t.*,c.name customer_name,s.name service_name,u.name assignee FROM tickets t JOIN customers c ON c.id=t.customer_id JOIN services s ON s.id=t.service_id LEFT JOIN users u ON u.id=t.assigned_to WHERE t.business_id=?'; $params=[$user['business_id']]; if($user['role']!=='owner') { $sql.=' AND t.assigned_to=?'; $params[]=$user['id']; } return all($sql.$extra,array_merge($params,$args)); }

