    $titles=['dashboard'=>'Overview','tickets'=>'Service tickets','schedule'=>'Schedule','customers'=>'Customers','services'=>'Service catalog','quotes'=>'Quotes','invoices'=>'Billing','team'=>'Team','settings'=>'Settings','ticket'=>'Ticket details','new-ticket'=>'New service ticket'];
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102c35"><title><?=e($titles[$page]??ucfirst($page))?> · Worksnow</title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head><body class="<?=$public?'public-page':'workspace'?>">
    <?php if(!$public): ?><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">w<span>↗</span></span>worksnow<span class="brand-dot">.</span></a><div class="workspace-label">WORKSPACE</div><div class="business-pill"><span class="avatar"><?=e(strtoupper(substr($business['name'],0,1)))?></span><span><?=e($business['name'])?><small>Field service workspace</small></span></div><nav aria-label="Main navigation"><?php
    $nav=['dashboard'=>['grid','Overview'],'tickets'=>['ticket','Service tickets'],'schedule'=>['calendar','Schedule']];
    if($user['role']==='owner') $nav+=['customers'=>['users','Customers'],'services'=>['box','Service catalog'],'quotes'=>['file','Quotes'],'invoices'=>['money','Billing'],'team'=>['users','Team']];
    foreach($nav as $key=>[$ico,$label]): ?><a class="nav-link <?=$page===$key||($key==='tickets'&&in_array($page,['ticket','new-ticket']))?'active':''?>" href="<?=e(url(['page'=>$key]))?>"><?=icon($ico)?><span><?=e($label)?></span></a><?php endforeach; ?></nav><div class="sidebar-bottom"><div class="sidebar-tip"><span class="tip-icon"><?=icon('link')?></span><strong>Your service desk, online.</strong><p>Let customers request a service and follow every step.</p><a href="<?=e(url(['page'=>'request','business'=>$business['slug']]))?>" target="_blank" rel="noopener">Open request page ↗</a></div><a class="nav-link <?=$page==='settings'?'active':''?>" href="<?=e(url(['page'=>'settings']))?>"><?=icon('settings')?>Settings</a><div class="account"><span class="avatar user-avatar"><?=e(strtoupper(substr($user['name'],0,1)))?></span><div><?=e($user['name'])?><small><?=e(ucfirst($user['role']))?></small></div><?php start_form('logout',[],'logout-form'); ?><button aria-label="Sign out" class="icon-link"><?=icon('logout')?></button></form></div></div></aside><div class="workspace-main"><header class="topbar"><div class="breadcrumbs"><button class="icon-link mobile-menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="sidebar" data-menu>☰</button><span>Workspace</span><span class="slash">/</span><strong><?=e($titles[$page]??'Overview')?></strong></div><div class="topbar-right"><span class="today"><?=e(date('D, d M Y'))?></span><span class="live-dot"></span><span>All systems ready</span></div></header><main><?php else: ?><header class="public-header"><a class="brand dark" href="index.php"><span class="brand-mark">w<span>↗</span></span>worksnow<span class="brand-dot">.</span></a><a class="text-link" href="<?=e(url(['page'=>$user?'dashboard':'login']))?>"><?=$user?'Go to workspace':'Business sign in'?> <?=icon('arrow')?></a></header><main class="public-main <?=$page==='document'?'document-main':''?>"><?php endif; ?>
    <?php if($error): ?><div class="alert error" role="alert"><?=e($error)?></div><?php endif; ?>
    <?php if(isset($_SESSION['flash'])): [$msg,$type]=$_SESSION['flash']; unset($_SESSION['flash']); ?><div class="alert <?=e($type)?>" role="status"><?=icon('check')?><?=e($msg)?></div><?php endif; ?>
    <?=$content?></main><?php if(!$public): ?><footer class="workspace-footer"><span>Worksnow · A little less admin. A lot more service.</span><span><?=e($business['currency'])?> · <?=e(date_default_timezone_get())?></span></footer></div><?php else: ?><footer class="public-footer">Powered by Worksnow · Service, from request to resolution.</footer><?php endif; ?></body></html><?php
}

function render_page(string $page): void {
    global $user,$business;
    if(in_array($page,['login','register'],true)) { render_auth($page); return; }
    if($page==='request') { render_request(); return; }
    if($page==='track') { render_track(); return; }
    if($page==='document') { render_document(); return; }
    if(!$user) throw new DomainException('Sign in to continue.');
    if(in_array($page,['customers','services','quotes','invoices','team','new-ticket'],true)) owner();
    switch($page) {
        case 'dashboard': render_dashboard(); break;
        case 'tickets': render_tickets(); break;
        case 'schedule': render_schedule(); break;
        case 'new-ticket': render_new_ticket(); break;
        case 'ticket': render_ticket(); break;
        case 'services': render_services(); break;
        case 'customers': render_customers(); break;
        case 'quotes': case 'invoices': render_documents($page); break;
        case 'team': render_team(); break;
        case 'settings': render_settings(); break;
        default: throw new DomainException('This page does not exist.');
    }
}

function render_auth(string $page): void {
    $register=$page==='register'; ?>
    <section class="auth-shell"><div class="auth-story"><div class="eyebrow">BUILT FOR THE WORK OUT THERE</div><h1>Great service.<br>From the first request<br>to the final invoice<span>.</span></h1><p>One clear workspace for your customers, your field team, and everything that keeps your business moving.</p><div class="story-flow"><span><?=icon('ticket')?>Request</span><i>→</i><span><?=icon('wrench')?>Resolve</span><i>→</i><span><?=icon('check')?>Get paid</span></div><div class="story-note"><span class="live-dot"></span>Less paperwork. More work that matters.</div></div><div class="auth-card"><span class="pill">YOUR SERVICE BUSINESS, CONNECTED</span><h2><?=$register?'Make room for better work.':'Welcome back.'?></h2><p><?=$register?'Create your business workspace. No credit card required.':'Sign in to see what’s happening in the field.'?></p><?php start_form($register?'register':'login',[],'auth-form');
    if($register) { field('Your name','name','text','',true,'autocomplete="name" maxlength="150"'); field('Business name','company','text','',true,'maxlength="150"'); field('Business link','slug','text','',true,'pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="e.g. acme-services" maxlength="60"'); echo '<small class="hint">Your customers use this link to request service.</small>'; }
    field('Email address','email','email','',true,'autocomplete="username" maxlength="190"'); field('Password','password','password','',true,'autocomplete="'.($register?'new-password':'current-password').'" '.($register?'minlength="12" maxlength="72"':'maxlength="72"'));
    if($register) { echo '<small class="hint">Use at least 12 characters.</small><div class="form-grid">'; select_field('Currency','currency',['THB'=>'THB · Thai baht','USD'=>'USD · US dollar','EUR'=>'EUR · Euro','GBP'=>'GBP · Pound','AUD'=>'AUD · Australian dollar','SGD'=>'SGD · Singapore dollar'],'THB'); field('Phone (optional)','phone','tel','',false,'maxlength="60"'); echo '</div>'; }
    end_form($register?'Create workspace →':'Sign in →'); ?><p class="auth-switch"><?=$register?'Already have a workspace?':'New to Worksnow?'?> <a href="<?=e(url(['page'=>$register?'login':'register']))?>"><?=$register?'Sign in':'Create a workspace'?></a></p></div></section><?php
}

function render_dashboard(): void {
    global $user,$business;
    $tickets=ticket_query(' ORDER BY t.created_at DESC,t.id DESC'); $active=array_filter($tickets,fn($t)=>!in_array($t['status'],['completed','cancelled'],true));
    $today=array_filter($active,fn($t)=>substr($t['scheduled_at'],0,10)===date('Y-m-d'));
    usort($today,fn($a,$b)=>strcmp($a['scheduled_at'],$b['scheduled_at']));
    $completed=count(array_filter($tickets,fn($t)=>$t['status']==='completed'));
    $receivable=$user['role']==='owner'?(int)q("SELECT COALESCE(SUM(total-paid),0) FROM documents WHERE business_id=? AND kind='invoice' AND status IN ('sent','partial')",[$user['business_id']])->fetchColumn():0;
    heading('YOUR DAY, AT A GLANCE','Let’s get good work done, '.explode(' ',$user['name'])[0].'.','Here’s what’s happening across your service business.',$user['role']==='owner'?'<a class="button" href="'.e(url(['page'=>'new-ticket'])).'">'.icon('plus').' Create ticket</a>':'');
    ?><div class="metric-grid"><article class="metric"><div><span>Active tickets</span><span class="metric-icon teal"><?=icon('ticket')?></span></div><strong><?=count($active)?></strong><small>Requests that need your attention</small></article><article class="metric"><div><span>Scheduled today</span><span class="metric-icon blue"><?=icon('calendar')?></span></div><strong><?=count($today)?></strong><small><?=e(date('l, d F'))?></small></article><article class="metric"><div><span>Completed jobs</span><span class="metric-icon green"><?=icon('check')?></span></div><strong><?=$completed?></strong><small>Resolved, repaired, ready to go</small></article><article class="metric"><div><span><?=$user['role']==='owner'?'Outstanding invoices':'Your assignments'?></span><span class="metric-icon amber"><?=icon('money')?></span></div><strong class="money-metric"><?=$user['role']==='owner'?e(money($receivable)):count($tickets)?></strong><small><?=$user['role']==='owner'?'Issued balances awaiting payment':'Tickets assigned to you'?></small></article></div>
    <div class="dashboard-columns"><section class="panel"><div class="panel-heading"><div><h2>Recent service tickets <span class="count"><?=count($tickets)?></span></h2><p>Your latest requests and ongoing work.</p></div><a class="text-link" href="<?=e(url(['page'=>'tickets']))?>">View all <?=icon('arrow')?></a></div><?php ticket_list(array_slice($tickets,0,6)); ?></section><section class="panel agenda"><div class="panel-heading"><div><h2>On the schedule</h2><p>Today · <?=e(date('d M'))?></p></div><?=icon('calendar')?></div><?php if(!$today): ?><div class="agenda-empty"><span class="metric-icon teal"><?=icon('calendar')?></span><h3>A little breathing room.</h3><p>No visits scheduled for today. Your next appointments will appear here.</p><a class="text-link" href="<?=e(url(['page'=>'schedule']))?>">Open schedule →</a></div><?php else: foreach($today as $t): ?><a class="agenda-item" href="<?=e(url(['page'=>'ticket','id'=>$t['id']]))?>"><strong><?=e(substr($t['scheduled_at'],11,5))?></strong><div><b><?=e($t['title'])?></b><small><?=e($t['customer_name'])?></small><small><?=e($t['assignee']??'Unassigned')?></small></div></a><?php endforeach; endif; ?></section></div>
    <section class="request-banner"><span class="banner-icon"><?=icon('link')?></span><div><h2>Make it easy to ask for a hand.</h2><p>Share your request page. Customers can book a service and track the work in one place.</p></div><a class="button secondary" href="<?=e(url(['page'=>'request','business'=>$business['slug']]))?>" target="_blank" rel="noopener">Your request page ↗</a></section><?php
}

function render_tickets(): void {
    global $user;
    $filter=(string)($_GET['status']??''); $search=trim((string)($_GET['search']??'')); $extra=''; $args=[];
    if(array_key_exists($filter,status_options())) { $extra.=' AND t.status=?'; $args[]=$filter; }
    if($search!=='') { $extra.=' AND (t.title LIKE ? OR c.name LIKE ? OR t.id=?)'; $args[]='%'.$search.'%'; $args[]='%'.$search.'%'; $args[]=(int)preg_replace('/\D/','',$search); }
    heading('SERVICE OPERATIONS','Every request. One clear view.','Keep your jobs moving from the first call to a job well done.',$user['role']==='owner'?'<a class="button" href="'.e(url(['page'=>'new-ticket'])).'">'.icon('plus').' Create ticket</a>':'');
    ?><section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="tickets"><label class="search-field"><?=icon('search')?><input aria-label="Search tickets" name="search" placeholder="Search tickets or customers…" value="<?=e($search)?>"></label><select name="status" aria-label="Filter by status"><option value="">All statuses</option><?php foreach(status_options() as $k=>$v): ?><option value="<?=e($k)?>" <?=$filter===$k?'selected':''?>><?=e($v)?></option><?php endforeach; ?></select><button class="button secondary">Apply filters</button></form><?php ticket_list(ticket_query($extra.' ORDER BY t.id DESC',$args)); ?></section><?php
}

function render_schedule(): void {
    $tickets=ticket_query(" AND t.scheduled_at<>'' AND t.status NOT IN ('completed','cancelled') ORDER BY t.scheduled_at,t.id");
    heading('FIELD TEAM','The right person. The right place.','Upcoming and overdue visits in '.date_default_timezone_get().'.');
    echo '<section class="panel">'; if(!$tickets) empty_state('Your schedule is clear','Assign a date and technician from any ticket to plan a visit.');
    $day=''; foreach($tickets as $t) { $date=substr($t['scheduled_at'],0,10); if($date!==$day) { $day=$date; echo '<h2 class="date-heading">'.e(date('l, d F Y',strtotime($day))).($day<date('Y-m-d')?' <span class="badge urgent">Overdue</span>':'').'</h2>'; } echo '<a class="schedule-row" href="'.e(url(['page'=>'ticket','id'=>$t['id']])).'"><strong>'.e(substr($t['scheduled_at'],11,5)).'</strong><div><b>'.e($t['title']).'</b><small>'.e($t['customer_name'].' · '.$t['address']).'</small></div>'.badge($t['status']).'<span>'.e($t['assignee']??'Unassigned').'</span>'.icon('arrow').'</a>'; } echo '</section>';
}

function render_new_ticket(): void {
    global $user;
    $customers=all('SELECT * FROM customers WHERE business_id=? ORDER BY name',[$user['business_id']]); $services=all('SELECT * FROM services WHERE business_id=? AND active=1 ORDER BY name',[$user['business_id']]);
    heading('NEW REQUEST','Let’s get this on the board.','Capture the details, assign your team, and set the next step.');
    if(!$customers||!$services) { echo '<section class="panel">'; empty_state('A couple of things first','Add at least one customer and one active service before creating a ticket.',url(['page'=>!$services?'services':'customers']),!$services?'Add a service':'Add a customer'); echo '</section>'; return; }
    echo '<section class="panel padded narrow">'; start_form('ticket_create');
    select_field('Customer','customer_id',array_column($customers,'name','id')); select_field('Service','service_id',array_column($services,'name','id')); field('Ticket title','title','text','',true,'maxlength="180" placeholder="e.g. Air conditioner not cooling"'); select_field('Priority','priority',['low'=>'Low','normal'=>'Normal','high'=>'High','urgent'=>'Urgent'],'normal'); area('Request details','description'); area('Service address','address','',true); select_field('Assigned to','assigned_to',staff_options()); field('Appointment (optional)','scheduled_at','datetime-local','',false); end_form('Create ticket'); echo '</section>';
}

function render_ticket(): void {
    global $user;
    $t=ticket_access((int)($_GET['id']??0)); $customer=scoped('customers',(int)$t['customer_id']); $service=scoped('services',(int)$t['service_id']);
    heading(ticket_number((int)$t['id']).' · '.strtoupper($service['name']),$t['title'],'Created '.date('d M Y, H:i',strtotime($t['created_at'])),badge($t['status']));
    ?><div class="detail-grid"><div><section class="panel padded"><h2>Service details</h2><p class="preserve"><?=e($t['description']?:'No additional description.')?></p><div class="info-grid"><div><span>Customer</span><strong><?=e($customer['name'])?></strong><small><?=e($customer['email'])?></small><small><?=e($customer['phone'])?></small></div><div><span>Service location</span><strong class="preserve"><?=e($t['address'])?></strong></div></div><div class="share-box"><div><b>Customer tracking link</b><small>Anyone with this private link can track the ticket and respond to quotes.</small></div><a class="button secondary small" href="<?=e(public_link($t['token']))?>" target="_blank" rel="noopener">Open ↗</a><button class="button secondary small" data-copy="<?=e(public_link($t['token']))?>">Copy link</button></div></section>
    <section class="panel padded"><div class="panel-heading compact"><div><h2>Quotes & invoices</h2><p>Keep the cost of good service clear.</p></div></div><?php
    if($user['role']==='owner') {
        $docs=all('SELECT * FROM documents WHERE ticket_id=? AND business_id=? ORDER BY id DESC',[$t['id'],$user['business_id']]);
        if(!$docs) echo '<p class="muted">No documents yet. Build the first quote below.</p>';
        foreach($docs as $d) render_document_card($d,$t,false);
        ?><details class="form-details"><summary><?=icon('plus')?> Build a quote</summary><?php quote_form($t); ?></details><?php
    } else echo '<p class="muted">Quotes and billing are managed by the business owner.</p>'; ?></section>
    <section class="panel padded"><h2>Activity & customer updates</h2><p class="muted">Updates here are visible on the customer tracking page.</p><?php start_form('note',['id'=>$t['id']]); area('Add an update','message','',true); end_form('Post update'); render_activity((int)$t['id'],(int)$t['business_id']); ?></section></div><aside><section class="panel padded"><h2>Keep work moving</h2><?php start_form('ticket_update',['id'=>$t['id']],'stack-form'); select_field('Status','status',status_options(),$t['status']); if($user['role']==='owner') { select_field('Priority','priority',['low'=>'Low','normal'=>'Normal','high'=>'High','urgent'=>'Urgent'],$t['priority']); select_field('Assigned to','assigned_to',staff_options(),$t['assigned_to']??0); field('Appointment','scheduled_at','datetime-local',str_replace(' ','T',substr($t['scheduled_at'],0,16)),false); } end_form('Update ticket'); ?><p class="hint">Start work before completing a ticket. Completed jobs can be reopened to In progress.</p></section><section class="panel padded help-panel"><span class="metric-icon teal"><?=icon('check')?></span><h3>A clear next step helps everyone.</h3><p>Keep the status up to date so your customer always knows where things stand.</p></section></aside></div><?php
}
function render_activity(int $ticket,int $biz): void { echo '<ol class="timeline">'; foreach(all('SELECT * FROM activities WHERE ticket_id=? AND business_id=? ORDER BY id DESC',[$ticket,$biz]) as $a) echo '<li><span class="timeline-dot"></span><div><p class="preserve">'.e($a['message']).'</p><time>'.e(date('d M Y, H:i',strtotime($a['created_at']))).'</time></div></li>'; echo '</ol>'; }
function quote_form(array $t): void {
    start_form('quote_create',['ticket_id'=>$t['id']],'quote-form'); ?><div class="line-items" data-line-items><div class="line-item line-head"><span>Description</span><span>Qty</span><span>Unit price</span><span></span></div><?php for($i=0;$i<2;$i++): ?><div class="line-item"><input name="item_name[]" aria-label="Item description" placeholder="<?=$i===0?'Service / labor':'Parts / materials'?>" maxlength="200"><input name="item_qty[]" aria-label="Quantity" type="number" min="1" max="999" value="1"><input name="item_price[]" aria-label="Unit price" type="number" min="0" step="0.01" value="0.00"><button type="button" class="icon-link" data-remove-line aria-label="Remove item">×</button></div><?php endfor; ?></div><button type="button" class="text-link" data-add-line>+ Add line item</button><div class="form-grid"><?php field('Tax (%)','tax_rate','number','7',true,'min="0" max="100" step="0.01"'); field('Valid until (optional)','due_date','date','',false); ?></div><?php area('Notes / terms','notes'); end_form('Save draft quote');
}

function render_document_card(array $d,array $t,bool $public): void {
    echo '<article class="document-card"><div class="document-card-heading"><div><strong>'.e(doc_number($d)).'</strong> '.badge($d['status']).'<small>'.e(ucfirst($d['kind'])).($d['due_date']?' · '.($d['kind']==='quote'?'Valid until ':'Due ').e($d['due_date']):'').'</small></div><strong>'.e(money((int)$d['total'])).'</strong></div>';
    echo '<div class="document-actions"><a class="text-link" href="'.e(url(['page'=>'document','id'=>$d['id']]+($public?['token'=>$t['token']]:[]))).'" target="_blank" rel="noopener">View / print '.e($d['kind']).' ↗</a>';
    if(!$public && $d['status']==='draft') { start_form('document_send',['id'=>$d['id']],'inline-form'); echo '<button class="button small">Issue '.e($d['kind']).'</button></form>'; }
    if($public&&$d['kind']==='quote'&&$d['status']==='sent') {
        if($d['due_date']!==''&&$d['due_date']<date('Y-m-d')) echo '<span class="badge declined">Expired</span>';
        else { start_form('quote_response',['document_id'=>$d['id'],'token'=>$t['token']],'inline-form'); echo '<button class="button small" name="response" value="accepted" data-confirm="Accept this quote and its total?">Accept quote</button><button class="button secondary small" name="response" value="declined" data-confirm="Decline this quote?">Decline</button></form>'; }
    }
    echo '</div>';
    if(!$public&&$d['kind']==='quote'&&$d['status']==='accepted'&&!one('SELECT id FROM documents WHERE quote_id=? AND business_id=?',[$d['id'],$d['business_id']])) { echo '<details><summary>Create invoice from this quote</summary>'; start_form('invoice_create',['id'=>$d['id']]); field('Payment due','due_date','date',date('Y-m-d',strtotime('+14 days'))); area('Invoice notes / payment instructions','notes'); end_form('Create invoice draft'); echo '</details>'; }
    if($d['kind']==='invoice') { echo '<div class="balance"><span>Paid '.e(money((int)$d['paid'])).'</span><strong>Balance '.e(money((int)$d['total']-(int)$d['paid'])).'</strong></div>'; if(!$public&&in_array($d['status'],['sent','partial'],true)) { echo '<details><summary>Record a payment</summary>'; start_form('payment',['id'=>$d['id']]); field('Amount received','amount','number',number_format(((int)$d['total']-(int)$d['paid'])/100,2,'.',''),true,'min="0.01" step="0.01"'); select_field('Method','method',['bank_transfer'=>'Bank transfer','cash'=>'Cash','card'=>'Card (received externally)','other'=>'Other']); field('Reference (optional)','reference','text','',false,'maxlength="160"'); echo '<p class="hint full">Record payments you have received. Worksnow does not process or charge cards.</p>'; end_form('Record payment'); echo '</details>'; } }
    echo '</article>';
}

function render_services(): void {
    global $user,$business; heading('WHAT YOU DO BEST','Services worth showing up for.','Build your catalog. Active services are available on your customer request page.');
    echo '<div class="detail-grid"><section class="panel padded"><h2>Your service catalog</h2>';
    $services=all('SELECT * FROM services WHERE business_id=? ORDER BY id DESC',[$user['business_id']]); if(!$services) empty_state('Your first service starts here','Add the work your team offers, from a quick repair to regular maintenance.');
    foreach($services as $s) { echo '<details class="service-card"><summary><span class="metric-icon teal">'.icon('wrench').'</span><span><strong>'.e($s['name']).'</strong><small>From '.e(money((int)$s['price'])).' · '.($s['active']?'Active':'Hidden').'</small></span><span class="edit-label">Edit</span></summary>'; start_form('service_save',['id'=>$s['id']]); field('Service name','name','text',$s['name'],true,'maxlength="150"'); field('Starting price','price','number',number_format($s['price']/100,2,'.',''),true,'min="0" step="0.01"'); area('Description','description',$s['description']); echo '<label class="check-label"><input type="checkbox" name="active" '.($s['active']?'checked':'').'> Available for customer requests</label>'; end_form(); echo '</details>'; }
    echo '</section><section class="panel padded"><h2>Add a service</h2>'; start_form('service_save'); field('Service name','name','text','',true,'maxlength="150" placeholder="e.g. AC maintenance"'); field('Starting price','price','number','0.00',true,'min="0" step="0.01"'); area('Description','description'); echo '<p class="hint full">Starting prices are estimates. Final costs are agreed through a quote.</p>'; end_form('Add service'); echo '</section></div>';
}
function render_customers(): void {
    global $user; heading('YOUR RELATIONSHIPS','Good service starts with people.','Customer details and service locations, ready when your team needs them.');
    $customers=all('SELECT c.*,(SELECT COUNT(*) FROM tickets t WHERE t.customer_id=c.id AND t.business_id=c.business_id) jobs FROM customers c WHERE c.business_id=? ORDER BY c.id DESC',[$user['business_id']]);
    echo '<div class="detail-grid"><section class="panel"><div class="panel-heading"><h2>Customers <span class="count">'.count($customers).'</span></h2></div>';
    if(!$customers) empty_state('Meet your first customer','Add a customer here, or let them use your public request page.');
    else { echo '<div class="table-scroll"><table><thead><tr><th>Name</th><th>Contact</th><th>Service address</th><th>Tickets</th></tr></thead><tbody>'; foreach($customers as $c) echo '<tr><td><strong>'.e($c['name']).'</strong></td><td>'.e($c['email']).'<small>'.e($c['phone']).'</small></td><td>'.e($c['address']).'</td><td>'.(int)$c['jobs'].'</td></tr>'; echo '</tbody></table></div>'; }
    echo '</section><section class="panel padded"><h2>Add a customer</h2>'; start_form('customer_save',[],'stack-form'); field('Full name / company','name','text','',true,'maxlength="150"'); field('Email','email','email','',true,'maxlength="190"'); field('Phone','phone','tel','',false,'maxlength="60"'); area('Service address','address'); end_form('Add customer'); echo '</section></div>';
}
function render_documents(string $page): void {
    global $user; $kind=$page==='quotes'?'quote':'invoice'; heading($kind==='quote'?'CLEAR EXPECTATIONS':'THE BUSINESS SIDE',$kind==='quote'?'Agree on the work. And the cost.':'Good work deserves a clear invoice.',$kind==='quote'?'Create quotes inside a ticket. Customers accept or decline through their tracking link.':'Create invoices from accepted quotes and record payments as they arrive.');
    $docs=all('SELECT d.*,t.title,c.name customer_name FROM documents d JOIN tickets t ON t.id=d.ticket_id JOIN customers c ON c.id=t.customer_id WHERE d.business_id=? AND d.kind=? ORDER BY d.id DESC',[$user['business_id'],$kind]);
    echo '<section class="panel">'; if(!$docs) empty_state('No '.$page.' yet','Open a service ticket to build a quote and start the billing flow.',url(['page'=>'tickets']),'Open tickets');
    else { echo '<div class="table-scroll"><table><thead><tr><th>Document</th><th>Customer / ticket</th><th>Status</th><th>Total</th><th>'.($kind==='quote'?'Valid until':'Balance').'</th><th></th></tr></thead><tbody>'; foreach($docs as $d) echo '<tr><td><strong>'.e(doc_number($d)).'</strong><small>'.e(substr($d['created_at'],0,10)).'</small></td><td>'.e($d['customer_name']).'<small>'.e($d['title']).'</small></td><td>'.badge($d['status']).'</td><td>'.e(money((int)$d['total'])).'</td><td>'.e($kind==='quote'?($d['due_date']?:'No expiry'):money((int)$d['total']-(int)$d['paid'])).'</td><td><a class="text-link" href="'.e(url(['page'=>'ticket','id'=>$d['ticket_id']])).'">Open ticket →</a></td></tr>'; echo '</tbody></table></div>'; } echo '</section>';
}
function render_team(): void {
    global $user; heading('PEOPLE BEHIND THE WORK','Your team, in the loop.','Technicians see their assigned jobs and can update progress. Billing stays with the owner.');
    echo '<div class="detail-grid"><section class="panel padded"><h2>Team members</h2>'; foreach(all('SELECT name,email,role FROM users WHERE business_id=? ORDER BY id',[$user['business_id']]) as $u) echo '<div class="team-row"><span class="avatar user-avatar">'.e(strtoupper(substr($u['name'],0,1))).'</span><div><strong>'.e($u['name']).'</strong><small>'.e($u['email']).'</small></div>'.badge($u['role']).'</div>'; echo '</section><section class="panel padded"><h2>Add a technician</h2>'; start_form('team_create',[],'stack-form'); field('Full name','name','text','',true,'maxlength="150"'); field('Email address','email','email','',true,'maxlength="190"'); field('Initial password','password','password','',true,'minlength="12" maxlength="72" autocomplete="new-password"'); echo '<p class="hint">Share the initial password securely. Your teammate can change it in Settings.</p>'; end_form('Create technician account'); echo '</section></div>';
}
function render_settings(): void {
    global $user,$business; heading('WORKSPACE SETTINGS','The details behind your business.','Keep your contact information and account secure.'); echo '<div class="detail-grid">';
    if($user['role']==='owner') { echo '<section class="panel padded"><h2>Business details</h2>'; start_form('settings'); field('Business name','company','text',$business['name'],true,'maxlength="150"'); field('Contact email','email','email',$business['email'],true,'maxlength="190"'); field('Phone','phone','tel',$business['phone'],false,'maxlength="60"'); echo '<div><span class="hint">Business link</span><p>'.e($business['slug']).'</p></div><p class="hint full">Currency: '.e($business['currency']).'. Currency and business link stay fixed to keep existing documents consistent.</p>'; end_form(); echo '</section>'; }
    echo '<section class="panel padded"><h2>Change your password</h2>'; start_form('password',[],'stack-form'); field('Current password','current_password','password','',true,'autocomplete="current-password"'); field('New password','password','password','',true,'minlength="12" maxlength="72" autocomplete="new-password"'); end_form('Update password'); echo '</section></div>';
}

function render_request(): void {
    global $business; $business=one('SELECT * FROM businesses WHERE slug=?',[(string)($_GET['business']??'')]); if(!$business) throw new DomainException('This service business could not be found. Check the request link.');
    $services=all('SELECT * FROM services WHERE business_id=? AND active=1 ORDER BY name',[$business['id']]); ?>
    <div class="public-hero"><span class="pill"><?=e($business['name'])?> · CUSTOMER SERVICE DESK</span><h1>A little help.<br>A job well done.</h1><p>Tell us what you need. We’ll take it from here.</p></div><div class="request-grid"><section class="panel padded"><h2>Request a service</h2><p class="muted">You’ll get a private link to track your request and review quotes.</p><?php if(!$services) empty_state('Getting ready to help','This business is not accepting online requests yet. Please contact them directly.'); else { start_form('request',['business'=>$business['slug']]); select_field('What can we help with?','service_id',array_column($services,'name','id')); field('Request title','title','text','',true,'maxlength="180" placeholder="Briefly describe the problem"'); field('Your name','name','text','',true,'maxlength="150" autocomplete="name"'); field('Email address','email','email','',true,'maxlength="190" autocomplete="email"'); field('Phone number','phone','tel','',true,'maxlength="60" autocomplete="tel"'); area('Service address','address','',true); area('What’s happening?','description','',true); echo '<p class="hint full">We use these details to manage your request. Keep your tracking link private; it grants access to your request and quote approvals.</p>'; end_form('Send service request →'); } ?></section><aside><section class="panel padded"><h2>Here to help.</h2><p class="muted">Services offered by <?=e($business['name'])?>.</p><?php foreach($services as $s): ?><div class="public-service"><span class="metric-icon teal"><?=icon('wrench')?></span><div><h3><?=e($s['name'])?></h3><p><?=e($s['description'])?></p><strong>From <?=e(money((int)$s['price']))?></strong></div></div><?php endforeach; ?><div class="contact-block"><strong>Get in touch</strong><p><?=e($business['email'])?><br><?=e($business['phone'])?></p><small>Starting prices are estimates. You approve a quote before the final cost is agreed.</small></div></section></aside></div><?php
}
function public_ticket(): array { $token=(string)($_GET['token']??''); if(!preg_match('/^[a-f0-9]{64}$/',$token)) throw new DomainException('This private tracking link is invalid.'); $t=one('SELECT * FROM tickets WHERE token=?',[$token]); if(!$t) throw new DomainException('This private tracking link could not be found.'); return $t; }
function render_track(): void {
    global $business; $t=public_ticket(); $business=one('SELECT * FROM businesses WHERE id=?',[$t['business_id']]); $s=one('SELECT * FROM services WHERE id=? AND business_id=?',[$t['service_id'],$t['business_id']]);
    ?><div class="public-hero compact-hero"><span class="pill"><?=e($business['name'])?> · <?=ticket_number((int)$t['id'])?></span><h1>You’re in the loop.</h1><p>Every step of your service request, right here.</p></div><div class="detail-grid"><div><section class="panel padded"><div class="panel-heading compact"><h2><?=e($t['title'])?></h2><?=badge($t['status'])?></div><p class="preserve"><?=e($t['description'])?></p><div class="info-grid"><div><span>Service</span><strong><?=e($s['name'])?></strong></div><div><span>Appointment</span><strong><?=e($t['scheduled_at']?date('d M Y, H:i',strtotime($t['scheduled_at'])):'We’ll confirm a time')?></strong><small><?=e(date_default_timezone_get())?></small></div><div><span>Service address</span><strong class="preserve"><?=e($t['address'])?></strong></div></div></section><section class="panel padded"><h2>Your quotes & invoices</h2><p class="muted">Review the details before accepting a quote.</p><?php $docs=all("SELECT * FROM documents WHERE ticket_id=? AND business_id=? AND status<>'draft' ORDER BY id DESC",[$t['id'],$t['business_id']]); if(!$docs) echo '<p>Nothing to review yet. We’ll share the cost here when it’s ready.</p>'; foreach($docs as $d) render_document_card($d,$t,true); ?></section></div><aside><section class="panel padded"><h2>Progress updates</h2><?php render_activity((int)$t['id'],(int)$t['business_id']); ?></section><section class="panel padded"><h3>Need to talk?</h3><p><?=e($business['email'])?><br><?=e($business['phone'])?></p><p class="hint">Save this private link. No account is needed to follow your request.</p></section></aside></div><?php
}
function render_document(): void {
    global $user,$business; $id=(int)($_GET['id']??0); $token=(string)($_GET['token']??'');
    if($token!=='') { $t=public_ticket(); $d=one("SELECT * FROM documents WHERE id=? AND ticket_id=? AND business_id=? AND status<>'draft'",[$id,$t['id'],$t['business_id']]); }
    else { if(!$user) throw new DomainException('Use your private customer tracking link to view this document.'); owner(); $d=scoped('documents',$id); $t=scoped('tickets',(int)$d['ticket_id']); }
    if(!$d) throw new DomainException('This document is not available.');
    $business=one('SELECT * FROM businesses WHERE id=?',[$d['business_id']]); $c=one('SELECT * FROM customers WHERE id=? AND business_id=?',[$t['customer_id'],$t['business_id']]);
    ?><div class="print-toolbar"><a class="text-link" href="<?=e($token?public_link($token):url(['page'=>'ticket','id'=>$t['id']]))?>">← Back to ticket</a><button class="button secondary" data-print>Print / save PDF</button></div><article class="paper"><div class="invoice-heading"><div><div class="eyebrow"><?=e($business['name'])?></div><h1><?=e(ucfirst($d['kind']))?></h1><p><?=e($business['email'])?><br><?=e($business['phone'])?></p></div><div class="invoice-meta"><h2><?=e(doc_number($d))?></h2><?=badge($d['status'])?><p>Issued: <?=e(substr($d['created_at'],0,10))?><br><?=$d['kind']==='quote'?'Valid until':'Payment due'?>: <?=e($d['due_date']?:'Not specified')?></p></div></div><div class="info-grid"><div><span>Prepared for</span><strong><?=e($c['name'])?></strong><small><?=e($c['email'])?></small><small class="preserve"><?=e($t['address'])?></small></div><div><span>Service ticket</span><strong><?=ticket_number((int)$t['id'])?> · <?=e($t['title'])?></strong></div></div><div class="table-scroll"><table class="invoice-table"><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody><?php foreach(json_decode($d['items'],true,512,JSON_THROW_ON_ERROR) as $line): ?><tr><td><?=e($line['name'])?></td><td><?=(int)$line['qty']?></td><td><?=e(money((int)$line['price']))?></td><td><?=e(money((int)$line['total']))?></td></tr><?php endforeach; ?></tbody></table></div><div class="totals"><div><span>Subtotal</span><b><?=e(money((int)$d['subtotal']))?></b></div><div><span>Tax (<?=number_format($d['tax_rate']/100,2)?>%)</span><b><?=e(money((int)$d['tax']))?></b></div><div class="grand-total"><span>Total</span><b><?=e(money((int)$d['total']))?></b></div><?php if($d['kind']==='invoice'): ?><div><span>Payments received</span><b><?=e(money((int)$d['paid']))?></b></div><div><span>Balance due</span><b><?=e(money((int)$d['total']-(int)$d['paid']))?></b></div><?php endif; ?></div><?php if($d['notes']): ?><h3>Notes & terms</h3><p class="preserve"><?=e($d['notes'])?></p><?php endif; ?><?php if($d['kind']==='invoice'): $payments=all('SELECT * FROM payments WHERE document_id=? AND business_id=? ORDER BY id',[$d['id'],$d['business_id']]); if($payments): ?><h3>Payment history</h3><ul class="payment-history"><?php foreach($payments as $p): ?><li><?=e(substr($p['created_at'],0,10))?> · <?=e(money((int)$p['amount']))?> · <?=e(str_replace('_',' ',$p['method']))?> <?=e($p['reference'])?></li><?php endforeach; ?></ul><?php endif; endif; ?><div class="paper-footer">Thank you for choosing <?=e($business['name'])?>. <span>Powered by Worksnow</span></div></article><?php
}
